    questions: 30,
    content: "Opis quizu",
  },
  {
    id: "python-rozszerzenie-3",
    title: "Rozszerzenie – Quiz 1",
    level: "rozszerzony",
    questions: 30,
    content: "Opis quizu",
  },
];

const root = ReactDOM.createRoot(document.getElementById("root"));
